export interface Frontmatter {
  title?: string;
  date?: string;
  tags?: string[];
}

export interface Page {
  slug: string;
  link: string;
  outputPath: string;
  filePath: string;
  data: Frontmatter;
  content: string;
  html: string;
}

import matter from 'gray-matter';
import type { Frontmatter } from './types';

function toDateString(value: unknown): string | undefined {
  if (typeof value === 'string') return value;
  if (value instanceof Date) return value.toISOString();
  if (typeof value === 'number') return new Date(value).toISOString();
  return undefined;
}

export function parseFrontmatter(source: string): { data: Frontmatter; content: string } {
  const parsed = matter(source);
  const data: Frontmatter = {};

  if (parsed.data.title !== undefined) {
    data.title = String(parsed.data.title);
  }
  if (parsed.data.date !== undefined) {
    data.date = toDateString(parsed.data.date);
  }
  if (Array.isArray(parsed.data.tags)) {
    data.tags = parsed.data.tags.filter((tag): tag is string | number | boolean => tag !== null && tag !== undefined).map(String);
  }

  return { data, content: parsed.content };
}

import { marked } from 'marked';

export async function markdownToHtml(markdown: string): Promise<string> {
  const html = await marked.parse(markdown);
  return html.trim();
}

import type { Page } from './types';

export interface SiteConfig {
  title: string;
}

function escapeHtml(value: string): string {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function pageTitle(page: Page): string {
  return page.data.title ?? page.slug;
}

function layout(title: string, body: string): string {
  return [
    '<!DOCTYPE html>',
    '<html lang="en">',
    '<head>',
    '<meta charset="utf-8">',
    '<meta name="viewport" content="width=device-width, initial-scale=1">',
    `<title>${escapeHtml(title)}</title>`,
    '</head>',
    '<body>',
    body,
    '</body>',
    '</html>',
  ].join('\n');
}

export function renderPage(page: Page, config: SiteConfig): string {
  const title = pageTitle(page);
  const meta = page.data.date ? `<p class="date">${escapeHtml(page.data.date)}</p>` : '';
  const tags = page.data.tags && page.data.tags.length > 0
    ? `<p class="tags">${page.data.tags.map((tag) => `<span class="tag">${escapeHtml(tag)}</span>`).join(' ')}</p>`
    : '';
  const body = [
    '<header>',
    `<h1>${escapeHtml(title)}</h1>`,
    meta,
    tags,
    '</header>',
    '<main>',
    page.html,
    '</main>',
    `<footer>Generated by ${escapeHtml(config.title)}</footer>`,
  ].join('\n');
  return layout(title, body);
}

export function renderIndex(pages: Page[], config: SiteConfig): string {
  const sorted = [...pages].sort((a, b) => {
    const dateA = a.data.date ? Date.parse(a.data.date) : Number.NEGATIVE_INFINITY;
    const dateB = b.data.date ? Date.parse(b.data.date) : Number.NEGATIVE_INFINITY;
    if (dateA !== dateB) return dateB - dateA;
    return pageTitle(a).localeCompare(pageTitle(b));
  });

  const items = sorted.map((page) => {
    const date = page.data.date ? `<time datetime="${escapeHtml(page.data.date)}">${escapeHtml(page.data.date)}</time> ` : '';
    const tags = page.data.tags && page.data.tags.length > 0
      ? ` <em>(${page.data.tags.map((tag) => escapeHtml(tag)).join(', ')})</em>`
      : '';
    return `<li><a href="${escapeHtml(page.link)}">${escapeHtml(pageTitle(page))}</a> ${date}${tags}</li>`;
  }).join('\n');

  const body = [
    '<header>',
    `<h1>${escapeHtml(config.title)}</h1>`,
    '</header>',
    '<main>',
    sorted.length > 0 ? `<ul>\n${items}\n</ul>` : '<p>No pages found.</p>',
    '</main>',
  ].join('\n');

  return layout(config.title, body);
}

import * as fs from 'fs';
import * as path from 'path';
import { parseFrontmatter } from './frontmatter';
import { markdownToHtml } from './markdown';
import { renderIndex, renderPage, SiteConfig } from './template';
import type { Page } from './types';

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
  siteTitle?: string;
}

export const DEFAULT_CONTENT_DIR = './content';
export const DEFAULT_OUTPUT_DIR = './dist';
export const DEFAULT_SITE_TITLE = 'My Static Site';

const MARKDOWN_EXTENSION = /\.(md|markdown)$/i;

export function collectMarkdownFiles(contentDir: string): string[] {
  if (!fs.existsSync(contentDir)) return [];

  const files: string[] = [];
  const walk = (dir: string): void => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(full);
      } else if (entry.isFile() && MARKDOWN_EXTENSION.test(entry.name)) {
        files.push(full);
      }
    }
  };
  walk(contentDir);
  return files.sort();
}

export function slugFor(filePath: string, contentDir: string): string {
  const relative = path.relative(contentDir, filePath).replace(/\\/g, '/');
  return relative.replace(MARKDOWN_EXTENSION, '');
}

export async function buildSite(options: BuildOptions): Promise<Page[]> {
  const contentDir = path.resolve(options.contentDir);
  const outputDir = path.resolve(options.outputDir);
  const config: SiteConfig = { title: options.siteTitle ?? DEFAULT_SITE_TITLE };

  const pages: Page[] = [];
  for (const file of collectMarkdownFiles(contentDir)) {
    const source = fs.readFileSync(file, 'utf8');
    const { data, content } = parseFrontmatter(source);
    const html = await markdownToHtml(content);
    const slug = slugFor(file, contentDir);
    pages.push({
      slug,
      link: `${slug}.html`,
      outputPath: path.join(outputDir, `${slug}.html`),
      filePath: file,
      data,
      content,
      html,
    });
  }

  fs.mkdirSync(outputDir, { recursive: true });

  for (const page of pages) {
    fs.mkdirSync(path.dirname(page.outputPath), { recursive: true });
    fs.writeFileSync(page.outputPath, renderPage(page, config), 'utf8');
  }

  fs.writeFileSync(path.join(outputDir, 'index.html'), renderIndex(pages, config), 'utf8');

  return pages;
}

#!/usr/bin/env node

import * as path from 'path';
import { buildSite, DEFAULT_CONTENT_DIR, DEFAULT_OUTPUT_DIR, DEFAULT_SITE_TITLE } from './build';

export interface CliOptions {
  contentDir: string;
  outputDir: string;
  siteTitle: string;
}

export function parseCliArgs(argv: string[]): CliOptions {
  const args = argv.slice(2);
  const options: CliOptions = {
    contentDir: DEFAULT_CONTENT_DIR,
    outputDir: DEFAULT_OUTPUT_DIR,
    siteTitle: DEFAULT_SITE_TITLE,
  };

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === '--content') {
      options.contentDir = args[++i] ?? DEFAULT_CONTENT_DIR;
    } else if (arg.startsWith('--content=')) {
      options.contentDir = arg.slice('--content='.length) || DEFAULT_CONTENT_DIR;
    } else if (arg === '--output') {
      options.outputDir = args[++i] ?? DEFAULT_OUTPUT_DIR;
    } else if (arg.startsWith('--output=')) {
      options.outputDir = arg.slice('--output='.length) || DEFAULT_OUTPUT_DIR;
    } else if (arg === '--title') {
      options.siteTitle = args[++i] ?? DEFAULT_SITE_TITLE;
    } else if (arg.startsWith('--title=')) {
      options.siteTitle = arg.slice('--title='.length) || DEFAULT_SITE_TITLE;
    } else if (arg === '--help' || arg === '-h') {
      options.help = true;
    } else if (arg === 'build') {
      // command marker, no-op
    } else {
      throw new Error(`Unknown argument: ${arg}`);
    }
  }

  return options;
}

function printUsage(): void {
  console.log('ssg build [options]');
  console.log('');
  console.log('Build a static site from Markdown files.');
  console.log('');
  console.log('Options:');
  console.log('  --content <dir>   Markdown content directory (default: ./content)');
  console.log('  --output <dir>    Output directory for generated HTML (default: ./dist)');
  console.log('  --title <text>    Site title used in the generated pages');
  console.log('  -h, --help        Show this help');
}

export async function run(argv: string[]): Promise<number> {
  let options: CliOptions;
  try {
    options = parseCliArgs(argv);
  } catch (error) {
    console.error(`Error: ${(error as Error).message}`);
    printUsage();
    return 1;
  }

  if (options.help) {
    printUsage();
    return 0;
  }

  try {
    const pages = await buildSite(options);
    const content = path.resolve(options.contentDir);
    const output = path.resolve(options.outputDir);
    console.log(`Generated ${pages.length} page(s) from ${content} into ${output}`);
    return 0;
  } catch (error) {
    console.error(`Build failed: ${(error as Error).message}`);
    return 1;
  }
}

export function main(): void {
  run(process.argv).then((code) => {
    process.exitCode = code;
  });
}

if (require.main === module) {
  main();
}

