import { markdownToHtml } from '../src/markdown';

describe('markdownToHtml', () => {
  it('converts a heading', async () => {
    const html = await markdownToHtml('# Hello');
    expect(html).toContain('<h1>Hello</h1>');
  });

  it('converts emphasis and links', async () => {
    const html = await markdownToHtml('A **bold** [link](https://example.com)');
    expect(html).toContain('<strong>bold</strong>');
    expect(html).toContain('<a href="https://example.com">link</a>');
  });

  it('converts unordered lists', async () => {
    const html = await markdownToHtml('- one\n- two\n- three');
    expect(html).toContain('<ul>');
    expect(html).toContain('<li>one</li>');
    expect(html).toContain('<li>three</li>');
  });

  it('converts fenced code blocks', async () => {
    const html = await markdownToHtml('```ts\nconst x = 1;\n```');
    expect(html).toContain('<pre>');
    expect(html).toContain('<code');
    expect(html).toContain('const x = 1;');
  });

  it('handles an empty string', async () => {
    const html = await markdownToHtml('');
    expect(html).toBe('');
  });
});

import { parseFrontmatter } from '../src/frontmatter';

describe('parseFrontmatter', () => {
  it('parses title, date and tags', () => {
    const source = [
      '---',
      'title: My First Post',
      'date: 2024-03-01',
      'tags:',
      '  - javascript',
      '  - typescript',
      '---',
      '# Body',
      '',
      'Some **content**.',
    ].join('\n');

    const { data, content } = parseFrontmatter(source);

    expect(data.title).toBe('My First Post');
    expect(data.date).toBe('2024-03-01');
    expect(data.tags).toEqual(['javascript', 'typescript']);
    expect(content).toContain('# Body');
    expect(content).toContain('Some **content**.');
    expect(content).not.toContain('title:');
  });

  it('returns the whole string as content when there is no frontmatter', () => {
    const { data, content } = parseFrontmatter('# No metadata here');
    expect(data).toEqual({});
    expect(content).toBe('# No metadata here');
  });

  it('keeps the raw content body intact', () => {
    const { content } = parseFrontmatter('---\ntitle: Only Title\n---\n\nThis is the body.\n');
